EAAC,CACV,CAAC;IACN,CAAC;IAED,OAAO,CACH,KAAC,KAAK,CAAC,QAAQ,cACX,eAAK,SAAS,EAAE,kBAAkB,CAAC,WAAW,CAAC,EAAE,IAAI,EAAC,OAAO,aACzD,kBACI,GAAG,EAAE,GAAG,EACR,SAAS,EAAE,wBAAwB,CAAC,UAAU,EAAE,SAAS,CAAC,EAC1D,IAAI,EAAC,QAAQ,aACJ,EAAE,EACX,KAAK,EAAE,KAAK,EACZ,QAAQ,EAAE,CAAC,KACP,YAAY,qBACC,UAAU,aAG1B,KAAK,IAAI,CACN,eACI,EAAE,EAAE,OAAO,EACX,SAAS,EAAE,kBAAkB,CAAC,OAAO,CAAC,iBAC1B,MAAM,YAEjB,KAAK,GACH,CACV,EACA,eAAe,IAAI,CAChB,eAAM,SAAS,EAAE,kBAAkB,CAAC,aAAa,CAAC,YAAG,WAAW,GAAQ,CAC3E,EACA,QAAQ,IAAI,CACT,eAAM,SAAS,EAAE,kBAAkB,CAAC,aAAa,CAAC,YAC7C,sBAAsB,GACpB,CACV,IACI,EACR,sBAAsB,EAAE,EACxB,eAAe,CAAC,EAAE,CAAC,EAEnB,YAAY,IAAI,CACb,KAAC,OAAO,IACJ,SAAS,EAAE,SAAS,KAAK,KAAK,CAAC,CAAC,CAAC,CAAC,MAAM,EAAE,QAAQ,CAAC,CAAC,CAAC,CAAC,CAAC,OAAO,EAAE,QAAQ,CAAC,EACzE,QAAQ,QACR,SAAS,EAAE,kBAAkB,CAAC,eAAe,CAAC,EAC9C,OAAO,EACH,KAAC,KAAK,IACF,SAAS,EAAE,kBAAkB,CAAC,uBAAuB,CAAC,EACtD,KAAK,EAAC,OAAO,EACb,OAAO,EAAE,cAAK,IAAI,EAAC,cAAc,YAAE,YAAY,GAAO,GACxD,YAGN,+BACgB,CAAC,CAAC,uBAAuB,CAAC,EACtC,IAAI,EAAE,QAAQ,EACd,SAAS,EAAE,kBAAkB,CAAC,YAAY,CAAC,YAE3C,KAAC,IAAI,IAAC,IAAI,EAAE,mBAAmB,EAAE,IAAI,EAAE,IAAI,KAAK,GAAG,CAAC,CAAC,CAAC,EAAE,CAAC,CAAC,CAAC,EAAE,GAAI,GAC5D,GACH,CACb,EAED,KAAC,IAAI,IACD,SAAS,EAAE,kBAAkB,CAAC,cAAc,EAAE,EAAC,QAAQ,EAAC,CAAC,EACzD,IAAI,EAAE,WAAW,iBACL,MAAM,GACpB,IACA,GACO,CACpB,CAAC;AACN,CAAC,CAAC,CAAC;AAEH,aAAa,CAAC,WAAW,GAAG,eAAe,CAAC","sourcesContent":["'use client';

import * as React from 'react';

import {ChevronDown, TriangleExclamation} from '@gravity-ui/icons';

import {useUniqId} from '../../../../hooks';
import {Alert} from '../../../Alert';
import {Icon} from '../../../Icon';
import type {ListFocusOwner} from '../../../List';
import {Popover} from '../../../Popover';
import {useDirection} from '../../../theme';
import type {AriaLabelingProps} from '../../../types';
import type {CnMods} from '../../../utils/cn';
import {filterDOMProps} from '../../../utils/filterDOMProps';
import {selectControlBlock, selectControlButtonBlock} from '../../constants';
import i18n from '../../i18n';
import type {
    SelectProps,
    SelectRenderClearArgs,
    SelectRenderControl,
    SelectRenderCounter,
    SelectRenderTriggerProps,
} from '../../types';
import {SelectClear} from '../SelectClear/SelectClear';
import {SelectCounter} from '../SelectCounter/SelectCounter';

import './SelectControl.scss';

type ControlProps = {
    toggleOpen: () => void;
    renderControl?: SelectRenderControl<HTMLElement, any>;
    renderCounter?: SelectRenderCounter;
    view: NonNullable<SelectProps['view']>;
    size: NonNullable<SelectProps['size']>;
    pin: NonNullable<SelectProps['pin']>;
    selectedOptionsContent: React.ReactNode;
    className?: string;
    qa?: string;
    label?: string;
    placeholder?: SelectProps['placeholder'];
    isErrorVisible?: boolean;
    errorMessage?: SelectProps['errorMessage'];
    disabled?: boolean;
    value: unknown[];
    /** The values that count as selected: an empty one without an option does not */
    selectedCount: number;
    clearValue: () => void;
    hasClear?: boolean;
    hasCounter?: boolean;
    title?: string;
    onKeyDown?: (e: React.KeyboardEvent<HTMLElement>) => void;
    open: boolean;
    popupId: string;
    selectId: string;
    /**
     * The focus owner of the list (`useListFocusOwner`): the trigger is one of its two elements,
     * the filter input is the other. Optional — without it the trigger keeps the combobox props of
     * its own, but there is no `aria-activedescendant`
     */
    focusOwner?: ListFocusOwner;
} & AriaLabelingProps;

export const SelectControl = React.forwardRef<HTMLButtonElement, ControlProps>((props, ref) => {
    const {
        toggleOpen,
        clearValue,
        onKeyDown,
        renderControl,
        view,
        size,
        pin,
        selectedOptionsContent,
        className,
        qa,
        label,
        placeholder,
        isErrorVisible,
        errorMessage,
        open,
        disabled,
        value,
        selectedCount,
        hasClear,
        popupId,
        selectId,
        focusOwner,
        renderCounter,
        hasCounter,
        title,
    } = props;
    const hasValue = selectedCount > 0;
    // A selected option whose text is empty is still a value: the placeholder would deny it
    const showPlaceholder = Boolean(placeholder && !hasValue);

    const direction = useDirection();
    const labelId = useUniqId();

    const [isDisabledButtonAnimation, setIsDisabledButtonAnimation] = React.useState(false);

    const controlMods: CnMods = {
        open,
        size,
        pin,
        disabled,
        error: isErrorVisible,
        'has-clear': hasClear,
        'no-active': isDisabledButtonAnimation,
        'has-value': hasValue,
    };

    const buttonMods: CnMods = {
        open,
        size,
        view,
        pin,
        disabled,
        error: isErrorVisible,
    };

    const handleControlClick = React.useCallback(
        (e?: React.MouseEvent<HTMLElement>) => {
            // Fix for Safari
            // https://developer.mozilla.org/en-US/docs/Web/HTML/Element/button#clicking_and_focus
            if (e && e.currentTarget !== document.activeElement && 'focus' in e.currentTarget) {
                e.currentTarget.focus();
            }

            toggleOpen();
        },
        [toggleOpen],
    );

    const disableButtonAnimation = React.useCallback(() => {
        setIsDisabledButtonAnimation(true);
    }, []);
    const enableButtonAnimation = React.useCallback(() => {
        setIsDisabledButtonAnimation(false);
    }, []);
    const handleOnClearIconClick = React.useCallback(() => {
        // return animation on clear click
        setIsDisabledButtonAnimation(false);
        clearValue();
    }, [clearValue]);

    const renderCounterComponent = () => {
        if (!hasCounter) {
            return null;
        }
        const count = selectedCount;
        const counterComponent = <SelectCounter count={count} size={size} disabled={disabled} />;
        return renderCounter
            ? renderCounter(counterComponent, {count, size, disabled})
            : counterComponent;
    };

    const renderClearIcon = (args: SelectRenderClearArgs) => {
        if (!hasClear || !hasValue || disabled) {
            return null;
        }
        return (
            <SelectClear
                size={size}
                onClick={handleOnClearIconClick}
                onMouseEnter={disableButtonAnimation}
                onMouseLeave={enableButtonAnimation}
                renderIcon={args.renderIcon}
            />
        );
    };

    // `aria-expanded` and `aria-controls` are the state of the Select rather than the state of the
    // list: on mobile the Sheet keeps the list mounted for the whole closing animation
    const ownProps = {
        ...filterDOMProps(props, {labelable: true}),
        id: selectId,
        role: 'combobox',
        'aria-controls': open ? popupId : undefined,
        'aria-haspopup': 'listbox',
        'aria-expanded': open,
        'aria-invalid': isErrorVisible || undefined,
        onClick: handleControlClick,
        onKeyDown,
    } as const;

    // `disabled` is not a DOM prop of every element, and `aria-controls` has to be written after
    // the composition rather than through it: an `undefined` override never erases the value of
    // the owner, and the list outlives the Select while the popup animates out
    const triggerProps: SelectRenderTriggerProps = {
        ...(focusOwner ? focusOwner.getInputProps(ownProps) : ownProps),
        'aria-controls': open ? popupId : undefined,
        disabled,
    };

    // `aria-labelledby` overrides `aria-label`, so the trigger references itself to keep it in the name
    const labelledBy = label
        ? [triggerProps['aria-label'] && selectId, triggerProps['aria-labelledby'], labelId]
              .filter(Boolean)
              .join(' ')
        : triggerProps['aria-labelledby'];

    const {t} = i18n.useTranslation();

    if (renderControl) {
        return renderControl(
            {
                onClear: clearValue,
                renderClear: renderClearIcon,
                renderCounter: renderCounterComponent,
                ref,
                open,
                disabled,
                triggerProps,
            },
            {value},
        );
    }

    return (
        <React.Fragment>
            <div className={selectControlBlock(controlMods)} role="group">
                <button
                    ref={ref}
                    className={selectControlButtonBlock(buttonMods, className)}
                    type="button"
                    data-qa={qa}
                    title={title}
                    tabIndex={0}
                    {...triggerProps}
                    aria-labelledby={labelledBy}
                >
                    {/* hidden from the content so that it names the combobox instead of joining its value */}
                    {label && (
                        <span
                            id={labelId}
                            className={selectControlBlock('label')}
                            aria-hidden="true"
                        >
                            {label}
                        </span>
                    )}
                    {showPlaceholder && (
                        <span className={selectControlBlock('placeholder')}>{placeholder}</span>
                    )}
                    {hasValue && (
                        <span className={selectControlBlock('option-text')}>
                            {selectedOptionsContent}
                        </span>
                    )}
                </button>
                {renderCounterComponent()}
                {renderClearIcon({})}

                {errorMessage && (
                    <Popover
                        placement={direction === 'rtl' ? ['left', 'bottom'] : ['right', 'bottom']}
                        hasArrow
                        className={selectControlBlock('error-popover')}
                        content={
                            <Alert
                                className={selectControlBlock('error-popover-content')}
                                theme="clear"
                                message={<div role="presentation">{errorMessage}</div>}
                            />
                        }
                    >
                        <button
                            aria-label={t('label_show-error-info')}
                            type={'button'}
                            className={selectControlBlock('error-icon')}
                        >
                            <Icon data={TriangleExclamation} size={size === 's' ? 12 : 16} />
                        </button>
                    </Popover>
                )}

                <Icon
                    className={selectControlBlock('chevron-icon', {disabled})}
                    data={ChevronDown}
                    aria-hidden="true"
                />
            </div>
        </React.Fragment>
    );
});

SelectControl.displayName = 'SelectControl';
