                    onUpdate={onUpdate}
                    page={resultPage}
                    pageSize={pageSize}
                    pageSizeOptions={pageSizeOptions}
                    size={size}
                    total={resultTotal}
                    className={b('page-sizer')}
                    view={pageSizerView}
                />
            )}
